import { getCollectionNavigation } from '@dreadnought/core';

const items = [{ value: 'first' }, { value: 'hidden', disabled: true }, { value: 'last' }];
const next = getCollectionNavigation(items, 'first', 'ArrowRight', {
  orientation: 'horizontal',
  loop: false,
});
// next === 'last'; focus and selection are handled by the adapter.

import { getDraftTransition } from '@dreadnought/core';

const options = { format: (value: number | null) => value === null ? '' : String(value) };
const edited = getDraftTransition(9, { type: 'edit', draft: '10' }, options);
const confirmed = getDraftTransition(edited.value, { type: 'confirm', value: 10 }, options);
const cancelled = getDraftTransition(confirmed.value, { type: 'cancel' }, options);
const proposed = getDraftTransition(9, { type: 'confirm', value: 10 }, {
  ...options, controlled: true,
});
// confirmed: { value: 10, draft: '10', changed: true }
// cancelled: { value: 10, draft: '10', changed: false }
// proposed: { value: 9, draft: '9', changed: true }; proposal is action.value.
